package ro.leo.visual;
import ro.leo.i18n.L;import android.graphics.*;import android.widget.*;import java.util.*;import java.io.*;
public final class QrActivity extends PocketActivity {
 private String payload;private Bitmap image;private File last;
 protected void render(){list(L.t("Coduri QR"),Arrays.asList(L.t("Text sau link"),L.t("Partajează Wi-Fi"),L.t("Carte de contact"),L.t("Imagini QR salvate")),0,new Choice(){public void pick(int at){if(at==0)edit(L.t("Text sau link"),new String[]{L.t("Conținut")},new String[]{""},new Saved(){public void save(String[] v){show(v[0]);}},goHome());else if(at==1)edit(L.t("Partajează Wi-Fi"),new String[]{"SSID",L.t("Parolă · gol pentru rețea deschisă")},new String[]{"",""},new Saved(){public void save(String[] v){show(PocketQr.wifi(v[0],v[1],v[1].isEmpty()));}},goHome());else if(at==2)edit(L.t("Carte de contact"),new String[]{L.t("Nume"),L.t("Telefon")},new String[]{"",""},new Saved(){public void save(String[] v){show(PocketQr.contact(v[0],v[1]));}},goHome());else try{startActivity(new android.content.Intent(QrActivity.this,FilesActivity.class).putExtra("folder",PocketStore.folder(QrActivity.this,"QR").getPath()));}catch(Exception e){problem(e);}}},"",null);}
 private void show(String value){try{Bitmap next=PocketQr.bitmap(value,220);if(image!=null)image.recycle();image=next;payload=value;begin(L.t("Cod QR"));ImageView view=new ImageView(this);view.setImageBitmap(image);view.setScaleType(ImageView.ScaleType.CENTER);view.setBackgroundColor(Color.WHITE);root.addView(view,new LinearLayout.LayoutParams(-1,0,1));left=new Runnable(){public void run(){final String content=payload;options(L.t("Salvezi codul QR?"),new String[]{L.t("Anulează"),L.t("Salvează PNG · conține datele introduse")},new Choice(){public void pick(int yes){if(yes==1)job(L.t("Salvez PNG"),new Work(){public void run()throws Exception{last=PocketStore.output(QrActivity.this,"QR","code.png");Bitmap export=PocketQr.bitmap(content,600);try(FileOutputStream stream=new FileOutputStream(last)){if(!export.compress(Bitmap.CompressFormat.PNG,100,stream))throw new IOException("PNG failure");stream.getFD().sync();}finally{export.recycle();}}},new Runnable(){public void run(){exported(last);}});}});}};back=new Runnable(){public void run(){payload=null;if(image!=null){image.recycle();image=null;}home();}};footer(L.t("Salvează PNG"),"",L.t("Înapoi"));}catch(Exception e){problem(e);}}
 protected void onDestroy(){if(image!=null){image.recycle();image=null;}payload=null;super.onDestroy();}
}
